insert into public.protocolos (id, nombre, descripcion, horarios, pasos, requiere_foto, activo, fotos, medicion_etiqueta, medicion_unidad, registro, enlace_url, enlace_texto, roles) values ('89bfcf4c-3a1f-4ee8-9719-e44ab3a1d916', 'Conteo de elaborados (cocina)', 'Cocina cuenta los elaborados y carga las cantidades en la app. En la nota, lo que falta para mañana (le llega al encargado).', '{15:30,15:45}'::text[], E'{"Contar los elaborados de heladeras y cámara","Cargar cuánto hay de cada uno con el botón \\"Cargar el conteo\\""}'::text[], 'f', 't', '{"Foto de la heladera de elaborados"}'::text[], NULL, NULL, 'conteo_elaborados', '/cocina/elaborados?tab=contar', 'Cargar el conteo', '{cocina,chef}'::text[]) on conflict (id) do nothing;
insert into public.protocolos (id, nombre, descripcion, horarios, pasos, requiere_foto, activo, fotos, medicion_etiqueta, medicion_unidad, registro, enlace_url, enlace_texto, roles) values ('c9e36c34-70dc-4eea-bf42-5cd13a0a94b1', 'Control de descartables (barra)', 'El barista cuenta los vasos y los carga en Stock. En la nota, lo que haga falta pedir (les llega a los encargados).', '{08:30,16:30}'::text[], E'{"Contar los vasos de 6, 8, 12 y 18 oz y las tapas","Cargarlos con el botón \\"Contar los vasos\\" y guardar"}'::text[], 'f', 't', '{"Foto del estante de descartables"}'::text[], NULL, NULL, 'conteo_descartables', '/stock/conteo?area=descartables', 'Contar los vasos', NULL::text[]) on conflict (id) do nothing;
insert into public.protocolos (id, nombre, descripcion, horarios, pasos, requiere_foto, activo, fotos, medicion_etiqueta, medicion_unidad, registro, enlace_url, enlace_texto, roles) values ('383546f7-28c9-44cd-a1d1-b0d97a6e76d3', 'Control de tolva', 'Peso y foto de la tolva al abrir, en el cambio de turno y al cerrar. El peso pasa solo al registro de Tolva.', '{08:00,16:00,21:45}'::text[], '{"Pesar el café que hay en la tolva","Tolva tapada y molino limpio"}'::text[], 't', 't', '{"Foto de la tolva (que se vea el nivel)"}'::text[], 'Peso del café en la tolva', 'gr', 'tolva', NULL, NULL, NULL::text[]) on conflict (id) do nothing;
insert into public.protocolos (id, nombre, descripcion, horarios, pasos, requiere_foto, activo, fotos, medicion_etiqueta, medicion_unidad, registro, enlace_url, enlace_texto, roles) values ('e14b2c8b-cf95-4522-8609-8ee8423bea2b', 'Limpieza del baño', 'Protocolo obligatorio. Se completa con foto del baño terminado.', '{11:00,14:30,18:00,23:30}'::text[], '{"Inodoro y mingitorio limpios y desinfectados","Lavamanos, grifería y espejo limpios","Piso barrido y trapeado","Papel higiénico, jabón y toallas repuestos","Cesto vaciado con bolsa nueva","Sin olor: ventilación / aromatizante"}'::text[], 't', 't', '{"Foto general del baño","Foto de la basura (cesto con bolsa nueva)","Foto general del baño 2","foto de la basura 2 (cesto con bolsa nueva 2)"}'::text[], NULL, NULL, NULL, NULL, NULL, NULL::text[]) on conflict (id) do nothing;
